{
  "architecture": {
    "summary": "App dispatches events to internal SMS and external metrics/support channels via broker; failure paths route to external channels.",
    "components": [
      {
        "name": "app",
        "role": "Signup handler",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "r1",
        "role": "SMS delivery",
        "isolationStatus": "ISOLATED",
        "state": "OBSERVED"
      },
      {
        "name": "r2",
        "role": "Metrics delivery",
        "isolationStatus": "ISOLATED",
        "state": "OBSERVED"
      },
      {
        "name": "r3",
        "role": "Support delivery",
        "isolationStatus": "ISOLATED",
        "state": "OBSERVED"
      }
    ]
  },
  "flows": [
    {
      "source": "app",
      "target": "r1",
      "condition": "Normal delivery",
      "data": "Event with phone number",
      "boundary": "INTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "app",
      "target": "r2",
      "condition": "Normal delivery",
      "data": "Event with phone number",
      "boundary": "EXTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "app",
      "target": "r3",
      "condition": "Failure path",
      "data": "Event with phone number",
      "boundary": "EXTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "dispatcher.py",
      "target": "broker.py",
      "condition": "Publish event to channel",
      "data": "Channel + deep-copied event",
      "boundary": "UNKNOWN",
      "state": "INFERRED"
    }
  ],
  "uncertainties": [
    "Deployment.json boundary labels not verified in runtime behavior.",
    "Failure paths may expose raw phone to external recipients without mitigation."
  ]
}
